const {chromium}=require('playwright');const assert=require('node:assert/strict');
(async()=>{const base=process.env.ALPHA_BASE_URL||'https://tuuvo.app.br';const browser=await chromium.launch({headless:true,executablePath:process.env.CHROME_PATH||'/usr/bin/google-chrome'});try{
 const page=await browser.newPage({viewport:{width:1280,height:900}}),errors=[];page.on('pageerror',e=>errors.push(e.message));
 assert.equal((await page.goto(base+'/experience',{waitUntil:'networkidle'})).status(),200);await page.locator('#select-corporate').click();
 await page.locator('#introDetails').evaluate(e=>e.open=true);await page.getByRole('button',{name:'Reproduzir vídeo com narração',exact:true}).click();await page.waitForFunction(()=>{const v=document.querySelector('#introMedia video');return v.readyState>=2&&!v.paused&&v.currentTime>1});
 const audible=await page.locator('#introMedia video').evaluate(async video=>{const ctx=new AudioContext();await ctx.resume();const src=ctx.createMediaElementSource(video),a=ctx.createAnalyser();src.connect(a);a.connect(ctx.destination);window.__audio=ctx;const values=new Float32Array(a.fftSize);for(let i=0;i<50;i++){a.getFloatTimeDomainData(values);if(values.some(v=>Math.abs(v)>.002))return true;await new Promise(r=>setTimeout(r,50))}return false});assert.equal(audible,true);
 await page.getByRole('button',{name:'Começar a experiência',exact:true}).click();await page.locator('#context').waitFor({state:'visible'});assert.match(await page.locator('#caseMaterials').textContent(),/40 kits/);assert.match(await page.locator('#decisionTask').textContent(),/confirma com Marina/);assert.equal(await page.locator('#media').isVisible(),false);
 await page.screenshot({path:'/tmp/alpha-browser/marina-materiais.png',fullPage:true});
 const choose=async(id,next)=>{await page.locator(`[data-choice="${id}"]`).click();if(next)await page.waitForFunction(n=>document.querySelector('#phaseCount').textContent.includes('FASE '+n+' DE'),next);else await page.locator('#results').waitFor({state:'visible'})};
 await page.setViewportSize({width:390,height:844});await choose('transferir',2);assert.match(await page.locator('#caseMaterials').textContent(),/40 kits.*20 kits/s);assert.match(await page.locator('#phaseNotice').textContent(),/Fase 1 concluída/);assert.equal(await page.evaluate(()=>scrollY),0);await page.screenshot({path:'/tmp/alpha-browser/comprovante-mobile.png',fullPage:true});
 await page.locator('#leave').click();await page.reload({waitUntil:'networkidle'});await page.locator('#select-corporate').click();await page.getByRole('button',{name:'Retomar meu percurso',exact:true}).click();await page.waitForFunction(()=>document.querySelector('#phaseCount').textContent.includes('FASE 2 DE'));
 await choose('fechado',3);await choose('prometer',4);assert.match(await page.locator('#caseMaterials').textContent(),/horário ainda não confirmado/);assert.match(await page.locator('#caseMaterials').textContent(),/Entrega garantida/);await choose('repassar',5);await choose('encerrar',6);assert.match(await page.locator('#caseMaterials').textContent(),/Transferir a conversa/);await choose('seguir');assert.equal(await page.locator('#firstScore').textContent(),'0.0');assert.match(await page.locator('#evidence').textContent(),/20 dos 40/);
 await page.locator('#retry').click();for(const [i,id] of ['ouvir','comparar','confirmar','registrar','validar','rever'].entries())await choose(id,i<5?i+2:0);assert.equal(await page.locator('#currentScore').textContent(),'100.0');assert.equal(await page.locator('#firstScore').textContent(),'0.0');await page.waitForFunction(()=>document.querySelector('#comparison').getAttribute('aria-busy')==='false');assert.equal(await page.locator('#comparisonScore').textContent(),'0,0 / 100');await page.selectOption('#scope','A');await page.waitForFunction(()=>document.querySelector('#cohortText').textContent.includes('12'));
 const d=page.waitForEvent('download');await page.locator('#download').click();assert.equal((await d).suggestedFilename(),'tuuvo-minha-sintese.txt');await page.screenshot({path:'/tmp/alpha-browser/alpha-publicada.png',fullPage:true});assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);assert.deepEqual(errors,[]);console.log('PASS: practical corporate materials, explicit task, decisions reflected in documents, shuffled alternatives, narrated introduction, resume, two attempts, comparison, report and mobile');
}finally{await browser.close()}})().catch(e=>{console.error('::error title=Public journey validation::'+e.message.replace(/\n/g,'%0A').replace(/\r/g,'%0D'));process.exit(1)});
